// BuildGateway constructs the gateway root — every node its fields
// reach, once, dependencies first — then seals the graph. Start order as
// compose.go wires it today (stop is the reverse):
//
//	pprof → db_repo → nats_conn → user_update_hub → daemon_state_publisher → tool_result_publisher → tools_daemon → flow_health → tools_daemon_sweeper → state_derivation → jet_stream → tool_bridge → daemon_event_publisher → connection_listeners → activity_subscriber → tls_files → token_authority → daemon_auth → daemon_chain → daemon_routes → daemon_listener → daemon_connector → managed_reconciler
func (g *Graph) BuildGateway() (*Gateway, error) {
	if g.DatabaseConfig == nil {
		return nil, fmt.Errorf("build gateway: set app.Graph's DatabaseConfig before building the root: its closure reads it")
	}
	if g.GatewayConfig == nil {
		return nil, fmt.Errorf("build gateway: set app.Graph's GatewayConfig before building the root: its closure reads it")
	}
	if g.ServerProcessConfig == nil {
		return nil, fmt.Errorf("build gateway: set app.Graph's ServerProcessConfig before building the root: its closure reads it")
	}
	r := &Gateway{}
	err := g.build("gateway", func() {
		// Last field first, so the first field starts last and stops first.
		r.Pprof = g.Pprof()
		r.FlowHealth = g.FlowHealth()
		r.ToolsDaemon = g.ToolsDaemonSweeper()
		r.Derivation = g.StateDerivation()
		r.Bridge = g.ToolBridge()
		r.Listeners = g.ConnectionListeners()
		r.Activity = g.ActivitySubscriber()
		r.Daemon = g.DaemonListener()
		r.Reconciler = g.ManagedReconciler()
	})
	if err != nil {
		return nil, err
	}
	return r, nil
}

// RunGateway builds the gateway root and supervises what it built until
// ctx ends or a node fails: every node that reports Ready joins g.Probes'
// /readyz, and g.Probes' Drainer is the stop policy's readiness gate and
// budget unless policy names one.
// No node the root reaches serves g.Probes, so a probe listener on the server
// address does: started before every node, stopped after them.
func (g *Graph) RunGateway(ctx context.Context, policy lifecyclekit.Policy) error {
	if _, err := g.BuildGateway(); err != nil {
		return err
	}
	probes, err := g.probeListener()
	if err != nil {
		return fmt.Errorf("build gateway: %w", err)
	}
	return g.b.Supervise(ctx, policy, g.Probes, probes...)
}

