// probeListener serves g.Probes on the server address, for a root none of
// whose nodes does; nil when the graph has no Probes.
func (g *Graph) probeListener() ([]lifecyclekit.Node, error) {
	if g.Probes == nil {
		return nil, nil
	}
	l, err := serverkit.NewProbeListener(serverkit.ProbeListenerDeps{Config: g.ServerCfg.Listener(), Probes: g.Probes, Logger: g.Log})
	if err != nil {
		return nil, err
	}
	return []lifecyclekit.Node{{Name: "probe_listener", Run: l.Run, Drain: l.Drain, Close: l.Close, Ready: l.Ready}}, nil
}
